-- GenDB engine variant Q06-conjunct_permutation: template q06.sql, kind conjunct_permutation (generated by generate.py; frozen)
SELECT
  SUM(l_extendedprice * l_discount) AS revenue
FROM lineitem
WHERE
  l_quantity < $3
  AND l_discount BETWEEN $2 - 0.01 AND $2 + 0.01
  AND l_shipdate < $1 + INTERVAL '1 YEAR'
  AND l_shipdate >= $1
